#include "neural_chip/NeuralChipPipelineStateGate.h"
#include <cassert>
int main(){ dnxr::NeuralChipPipelineStateMachine sm; dnxr::NeuralChipAckHandshake ack; dnxr::PipelineResumeController rc; dnxr::NeuralChipPipelineStateGate g; sm.start(); auto d=g.evaluate(sm,ack,rc,0); assert(d.allowWorldProcessing); sm.onCommitAccepted(); ack.expect(1,0); d=g.evaluate(sm,ack,rc,10); assert(!d.allowWorldProcessing && d.waitOnly && !d.requireHold); d=g.evaluate(sm,ack,rc,100); assert(!d.allowWorldProcessing && d.requireHold && d.holdKind==dnxr::PipelineHoldKind::Decompression); sm.triggerEmergency("x"); d=g.evaluate(sm,ack,rc,100); assert(!d.allowWorldProcessing && d.holdKind==dnxr::PipelineHoldKind::Emergency); }
